package com.bank.ratehist;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TimeMapDemo {

    private static final Logger log = Logger.getLogger(TimeMapDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TimeMap rates = new TimeMap();

        // Savings interest rate changes over time (basis points), timestamps increasing.
        rates.set("SAVINGS_RATE", "350", 10);   // 3.50% at t=10
        rates.set("SAVINGS_RATE", "400", 20);   // 4.00% at t=20
        rates.set("SAVINGS_RATE", "425", 35);   // 4.25% at t=35

        log.info(() -> "rate at t=5  -> " + rates.get("SAVINGS_RATE", 5));    // before first: ""
        log.info(() -> "rate at t=10 -> " + rates.get("SAVINGS_RATE", 10));   // exactly first: 350
        log.info(() -> "rate at t=25 -> " + rates.get("SAVINGS_RATE", 25));   // between: 400
        log.info(() -> "rate at t=99 -> " + rates.get("SAVINGS_RATE", 99));   // after last: 425
    }
}

