class Entry {
    final int timestamp;
    final String value;

    Entry(int timestamp, String value) {
        this.timestamp = timestamp;
        this.value = value;
    }
}

// ─── Would be in TimeMap.java in a real project ───
class TimeMap {

    private static final Logger log = Logger.getLogger(TimeMap.class.getName());

    private final Map<String, List<Entry>> store = new HashMap<>();

    // O(1) amortized: append; assumes timestamps for a key arrive increasing.
    void set(String key, String value, int timestamp) {
        store.computeIfAbsent(key, k -> new ArrayList<>()).add(new Entry(timestamp, value));
        log.fine(() -> "set " + key + "=" + value + " @t=" + timestamp);
    }

    // O(log n): floor search for largest timestamp <= query.
    String get(String key, int timestamp) {
        List<Entry> history = store.get(key);
        if (history == null || history.isEmpty()) {
            return "";
        }
        int low = 0;
        int high = history.size() - 1;
        String answer = "";
        while (low <= high) {
            int mid = low + (high - low) / 2;
            Entry e = history.get(mid);
            if (e.timestamp <= timestamp) {
                answer = e.value;       // candidate; try to find a later valid one
                low = mid + 1;
            } else {
                high = mid - 1;         // too late; search earlier
            }
        }
        final String result = answer;
        log.fine(() -> "get " + key + " @t=" + timestamp + " -> '" + result + "'");
        return answer;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
